                  }}
                />
                <Scatter name="Vehicles" data={scatterData} fill="#0ea5e9">
                  {scatterData.map((d) => (
                    <Cell
                      key={d.id}
                      fill={d.lever === "housing-credit" ? "#f59e0b" : "#0ea5e9"}
