                <XAxis type="number" tickFormatter={(v) => `$${v}B`} stroke="#94a3b8" fontSize={11} />
                <YAxis
                  type="category"
                  dataKey="name"
                  width={140}
                  stroke="#94a3b8"
                  fontSize={11}
                  tickLine={false}
                />
                <Tooltip content={<BnTooltip />} />
                <Bar dataKey="bn" name="FY2026 cost" barSize={10} radius={[0, 4, 4, 0]}>
