                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
          <p className="mt-2 text-xs text-slate-500">
            JCT top-10 ??? {((JCT_AGGREGATE.top10ShareOfTotalApprox || 0) * 100).toFixed(0)}% of the{" "}
