                  name="Cumulative top-N"
                  stroke="#f59e0b"
                  fill="#fbbf24"
                  fillOpacity={0.35}
                />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      <p className="text-xs text-slate-500">Sources: {SOURCES.join(" ?? ")}</p>
    </div>
  );
}

